  var state = { loaded:false, loading:false, tenant:null, date:startDay(new Date()), view:'week', tab:'calendar', branch:'', professional:'', room:'', googleChangeId:null, canManage:false, canManagePatients:false, canReadClinical:false, branches:[], rooms:[], professionals:[], professionalBranches:[], services:[], professionalServices:[], hours:[], clinicHours:[], patients:[], appointments:[], blocks:[], requests:[], intakes:[], reminders:[], roles:[], rolePermissions:[], memberRoles:[] };

