  function emptyWeek(host,days){var active=days.map(function(day){return {day:day,availability:dayAvailability(day)};}),available=active.filter(function(x){return x.availability.count;}).length,first=active.find(function(x){return x.availability.count;}),start=first?new Date(first.day):new Date(days[0]);if(first)start.setHours(Number(first.availability.start.slice(0,2))||9,Number(first.availability.start.slice(3,5))||0,0,0);host.className='schedule-calendar week is-empty';host.innerHTML='<section class="schedule-week-empty"><div class="schedule-week-empty-copy"><span class="schedule-empty-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M8 3v4M16 3v4M3 10h18"/><path d="m9 15 2 2 4-4"/></svg></span><div><h3>No hay citas esta semana</h3><p>Elige un día para agendar.</p></div></div><div class="schedule-week-empty-actions">'+(state.canManage&&first?'<button type="button" class="btn btn-primary" data-book-slot="'+start.toISOString()+'" data-professional="'+esc(first.availability.professional)+'">Agendar una cita</button>':'')+'<button type="button" class="btn btn-secondary" data-empty-settings>Ver horarios</button></div><div class="schedule-week-availability" aria-label="Horarios configurados de la semana">'+active.map(function(x){var a=x.availability;return '<button type="button" '+(a.count?'data-book-slot="'+(function(){var d=new Date(x.day);d.setHours(Number(a.start.slice(0,2))||9,Number(a.start.slice(3,5))||0,0,0);return d.toISOString();})()+'" data-professional="'+esc(a.professional)+'"':'data-empty-settings')+'><span>'+DAYS[x.day.getDay()]+' '+x.day.getDate()+'</span><strong>'+(a.count?clock(a.start)+' a '+clock(a.end):'Cerrado')+'</strong><small>'+(a.count?'Agendar':'Definir horario')+'</small></button>';}).join('')+'</div><footer><span>Atiendes '+available+' de 7 días</span></footer></section>';}
  function renderWeek(host,r){var days=[];for(var i=0;i<7;i++)days.push(plusDays(r.start,i));var apps=visibleAppointments(),blocks=state.blocks.filter(function(b){return b.active&&filterRow(b);});if(!apps.length&&!blocks.length){emptyWeek(host,days);return;}if(window.SmylScheduleGrid)renderWeekGrid(host,days,apps,blocks);else renderWeekCards(host,days,apps,blocks);}
  function renderWeekCards(host,days,apps,blocks){host.className='schedule-calendar week';host.innerHTML=days.map(function(day){var key=isoDay(day),dayApps=apps.filter(function(a){return isoDay(a.starts_at)===key;}),dayBlocks=blocks.filter(function(b){return isoDay(b.starts_at)===key;}),availability=dayAvailability(day),emptyStart=new Date(day);emptyStart.setHours(Number(availability.start.slice(0,2))||9,Number(availability.start.slice(3,5))||0,0,0);return '<section class="schedule-day" data-today="'+(key===isoDay(new Date()))+'"><header><span>'+DAYS[day.getDay()]+'</span><strong>'+day.getDate()+'</strong></header><div class="schedule-day-body">'+(dayApps.map(appointmentCard).join('')+dayBlocks.map(blockCard).join('')||(availability.count?'<button type="button" class="schedule-day-empty" data-book-slot="'+emptyStart.toISOString()+'" data-professional="'+esc(availability.professional)+'"><span>Sin citas</span><small>'+clock(availability.start)+' a '+clock(availability.end)+'</small><strong>+ Agendar</strong></button>':'<button type="button" class="schedule-day-empty" data-empty-settings data-closed="true"><span>Cerrado</span><small>Definir horario</small></button>'))+'</div></section>';}).join('');}
