  function renderBookingCheck(form,appointment){var host=form.querySelector('[data-booking-check]'),x=bookingSnapshot(form,appointment),complete=x.service&&x.professional&&x.branch&&x.start,occupied=x.duration+x.extra+x.before+x.after,items=[['Dura',x.duration?x.duration+' min':'Elige un tratamiento'],['Reserva',occupied?occupied+' min'+(x.before||x.after?' con preparación':''):'—'],['Horario',x.start&&x.end?fmtRange({starts_at:x.start,ends_at:x.end}):'Elige día y hora'],['Atiende',x.professional?x.professional.display_name:'Elige quién atiende'],['Sillón',x.room?x.room.name:(x.branch&&state.rooms.some(function(r){return r.branch_id===x.branch.id;})?'Elige un sillón':'—')]];host.dataset.ready=String(!!complete&&!x.issues.length);host.innerHTML='<div class="schedule-booking-head"><div><span>RESUMEN</span><strong>'+(complete&&!x.issues.length?'Todo en orden':'Falta completar')+'</strong></div><i>'+(complete&&!x.issues.length?'✓':'!')+'</i></div><div class="schedule-booking-summary">'+items.map(function(i){return '<div><span>'+i[0]+'</span><strong>'+esc(i[1])+'</strong></div>';}).join('')+'</div>'+(x.issues.length?'<ul>'+x.issues.map(function(i){return '<li>'+esc(i)+'</li>';}).join('')+'</ul>':'');}
