    form.onsubmit=async function(event){event.preventDefault();var patientId=form.elements.patient.value;if(!patientId){notify('Selecciona un paciente existente o registra uno nuevo antes de continuar.','error');if(search)search.focus();return;}var button=form.querySelector('button[type="submit"]');button.disabled=true;button.textContent='Vinculando…';try{await rpc('smyl_link_public_appointment_intake',{p_request_id:request.id,p_patient_id:patientId});close();state.loaded=false;await load(true);var linked=byId(state.requests,request.id);notify('Contacto verificado y vinculado. Ahora revisa el horario antes de confirmar.','success');if(linked)openNew(linked,null,intakePreferredStart(intake));}catch(error){notify(message(error),'error');button.disabled=false;button.textContent='Vincular y continuar';}};
